const express = require("express");
const app = express();

// Synthetic error-handling middleware for a small internal API.
// Logs the error, maps known error codes to HTTP statuses, and
// returns a JSON error body to the client.
function errorHandler(err, req, res, next) {
  console.error(`[error] ${req.method} ${req.originalUrl}: ${err.message}`);

  if (err.code === "VALIDATION_FAILED") {
    res.status(422).json({
      error: "validation_failed",
      details: err.details || [],
    });
  }

  if (err.code === "NOT_FOUND") {
    res.status(404).json({ error: "not_found", resource: err.resource });
  }

  if (err.code === "UNAUTHORIZED") {
    res.status(401).json({ error: "unauthorized" });
  }

  if (err.statusCode && err.statusCode >= 500) {
    res.status(err.statusCode).json({ error: "internal_error" });
  }

  // Fallback for anything not matched above: log and hand off
  // to the default Express error handler.
  next(err);
}

app.get("/widgets/:id", (req, res, next) => {
  const widget = findWidget(req.params.id);
  if (!widget) {
    const err = new Error("widget not found");
    err.code = "NOT_FOUND";
    err.resource = "widget";
    return next(err);
  }
  res.json(widget);
});

app.use(errorHandler);

module.exports = { errorHandler };
